+        long totalDocs = 0;
+        for (int seg = 0; seg < numSegments; seg++) {
+            String segName = input.readString();
+            byte[] segmentID = new byte[StringHelper.ID_LENGTH];
+            input.readBytes(segmentID, 0, segmentID.length);
