+            if (softDelCount < 0 || softDelCount > si.maxDoc()) {
+                throw new IllegalStateException(
+                    "cannot write segment: invalid maxDoc segment=" + si.name + " maxDoc=" + si.maxDoc() + " softDelCount=" + softDelCount
